package com.library.service; import com.library.dao.BookDAO; import com.library.enums.Role; import com.library.exception.AuthorizationException; import com.library.model.Book; import com.library.session.SessionManager; import com.library.util.ValidationUtil; import java.util.*;
public class BookService { private final BookDAO dao=new BookDAO(); private void admin(){if(!SessionManager.hasRole(Role.ADMIN))throw new AuthorizationException("Admin access required.");} public List<Book> search(String term){return dao.findAll(term==null?"":term.trim());} public Book get(long id){return dao.findById(id);} public void save(Book b,boolean update){admin();validate(b);if(update)dao.update(b);else{b.setAvailableQuantity(b.getQuantity());dao.insert(b);}} public void deactivate(long id){admin();dao.deactivate(id);} private void validate(Book b){ValidationUtil.isbn(b.getIsbn());ValidationUtil.required(b.getBookName(),"Book name");ValidationUtil.required(b.getAuthor(),"Author");ValidationUtil.year(b.getPublicationYear());ValidationUtil.quantity(b.getQuantity());if(b.getCategoryId()<=0)throw new IllegalArgumentException("Select a category.");if(b.getAvailableQuantity()>b.getQuantity())throw new IllegalArgumentException("Available quantity cannot exceed total quantity.");} }
